using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Media;
namespace MRS;
public partial class MainWindow
{
 private static readonly LcnResearch sharedLcnResearch=new();private readonly DataGrid lcnResearchGrid=new(){AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,Background=Brushes.White,Foreground=Brushes.Black};private TabItem? lcnResearchTab;private readonly TextBlock lcnResearchStatus=new(){Foreground=Brushes.Aquamarine,TextWrapping=TextWrapping.Wrap};private string lcnResearchScope="";private FrequencyItem[] lcnResearchChannels=[];private readonly TextBox lcnControlFrequency=new(){Width=140};
 private void InitializeLcnResearch()
 {
  var panel=new DockPanel{Margin=new(10)};var head=new StackPanel();DockPanel.SetDock(head,Dock.Top);panel.Children.Add(head);var row=new WrapPanel();head.Children.Add(row);row.Children.Add(new TextBlock{Text="Control MHz ",Foreground=Brushes.Gainsboro});row.Children.Add(lcnControlFrequency);
  void Button(string title,Action action){var button=new Button{Content=title,Foreground=Brushes.Black,Padding=new(8,5,8,5),Margin=new(0,0,7,4)};row.Children.Add(button);button.Click+=(_,_)=>{try{action();}catch(Exception ex){lcnResearchStatus.Text=ex.Message;}};}
  Button("Start research",()=>{if(lcnResearchChannels.Length==0)throw new IOException("Right-click a DMR site folder in Frequencies and choose Research LCN map first.");sharedLcnResearch.Start(lcnResearchScope,CommercialParseMHz(lcnControlFrequency.Text),lcnResearchChannels.Select(c=>c.FrequencyHz));lcnResearchStatus.Text="Collecting CRC-valid grants and matching full voice LC across receivers. Candidates remain unconfirmed.";});Button("Stop",sharedLcnResearch.Stop);
  Button("Use candidate in DMR map",()=>{if(lcnResearchGrid.SelectedItem is not LcnCandidate candidate)return;if(dmrTrunkRadio.Running)throw new IOException("Stop DMR following before changing its carrier map.");if(candidate.Status.StartsWith("Conflicting"))throw new IOException("Resolve conflicting associations before using this candidate.");if(dmrTrunkMaps.Any(m=>m.Lcn==candidate.Lcn&&m.FrequencyMHz!=candidate.MHz))throw new IOException("This LCN already has another mapped frequency; review it first.");if(!dmrTrunkMaps.Any(m=>m.Lcn==candidate.Lcn))dmrTrunkMaps.Add(new(){Lcn=candidate.Lcn,FrequencyMHz=candidate.MHz,ColorCode=candidate.ColorCode,Confirmed=false,Evidence=$"{candidate.Matches} timed grant/full-LC correlations; unconfirmed; {candidate.Scope}"});SelectWorkspace(dmrTrunkFollowingTab!);});
  Button("Label saved channel as candidate",()=>{if(lcnResearchGrid.SelectedItem is LcnCandidate candidate){if(candidate.Status.StartsWith("Conflicting"))throw new IOException("Conflicting candidate cannot label a saved channel.");FrequencyManager.LabelLcnCandidate(candidate);}});
  Button("Export research CSV",()=>{var picker=new Microsoft.Win32.SaveFileDialog{Filter="CSV|*.csv",FileName="dmr-lcn-research.csv"};if(picker.ShowDialog(this)==true)PlanCsv.Write(picker.FileName,sharedLcnResearch.Snapshot().Select(c=>new Dictionary<string,string>{{"scope",c.Scope},{"lcn",c.Lcn.ToString()},{"frequency_mhz",c.MHz},{"slot",c.Slot.ToString()},{"talkgroup",c.Talkgroup.ToString()},{"color_code",c.ColorCode.ToString()},{"correlations",c.Matches.ToString()},{"seen_utc",c.Seen.ToString("O")},{"status",c.Status}}),["scope","lcn","frequency_mhz","slot","talkgroup","color_code","correlations","seen_utc","status"]);});
  head.Children.Add(lcnResearchStatus);head.Children.Add(new TextBlock{Text="Keep one receiver on control and decode candidate voice frequencies on other receivers. Select a single saved site folder to scope research. Only CRC-valid grants and validated group/slot/full voice LC within 1.5 seconds are correlated. A correlation is a candidate, not a proven mapping; repeated samples, collisions and conflicting activity require independent verification. No receiver is tuned or started automatically. Absolute-frequency/MBC decoding is still outside the current backend.",Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap,Margin=new(0,7,0,8)});
  foreach(var (title,path) in new[]{("LCN","Lcn"),("MHz","MHz"),("Slot","Slot"),("TG","Talkgroup"),("CC","ColorCode"),("Correlations","Matches"),("Status","Status"),("Scope","Scope")})lcnResearchGrid.Columns.Add(new DataGridTextColumn{Header=title,Binding=new Binding(path),MinWidth=70});panel.Children.Add(lcnResearchGrid);lcnResearchTab=new(){Header="Channel research",Content=panel};((TabControl)ProfessionalTab.Content).Items.Add(lcnResearchTab);
  FrequencyManager.ChannelResearchRequested+=(scope,entries)=>{lcnResearchScope=scope;lcnResearchChannels=entries;lcnControlFrequency.Text=PlanCsv.MHz(tunedHz);lcnResearchStatus.Text=$"Selected {scope}; {entries.Length} saved channel candidates. Check the control frequency and Start research.";SelectWorkspace(lcnResearchTab);};
 }
 private void TickLcnResearch(){if(lcnResearchTab?.IsSelected==true){var chosen=lcnResearchGrid.SelectedItem as LcnCandidate;lcnResearchGrid.ItemsSource=sharedLcnResearch.Snapshot();lcnResearchGrid.SelectedItem=lcnResearchGrid.Items.OfType<LcnCandidate>().FirstOrDefault(c=>c.Lcn==chosen?.Lcn&&c.Hz==chosen.Hz);}}
}
public sealed partial class FrequencyPanel
{
 internal event Action<string,FrequencyItem[]>? ChannelResearchRequested;
 private void ResearchFolder(Guid id)
 {var entries=RequireLibrary().ExportDiscoveries([id]).Channels.Where(c=>!c.IsFolder&&c.Protocols.Contains("DMR",StringComparison.OrdinalIgnoreCase)).ToArray();var scopes=entries.Select(c=>c.SiteScope).Where(s=>s.Length>0).Distinct().ToArray();if(scopes.Length!=1)throw new IOException("Choose a single DMR site folder with a known scope.");ChannelResearchRequested?.Invoke(scopes[0],entries);}
 internal void LabelLcnCandidate(LcnCandidate candidate)
 {var store=RequireLibrary();var matches=store.Items.Where(c=>!c.IsFolder&&c.SiteScope==candidate.Scope&&Math.Abs(c.FrequencyHz-candidate.Hz)<=1000).ToArray();if(matches.Length!=1)throw new IOException("Choose a uniquely matching saved site channel before labeling.");var old=matches[0];var updated=old with{ChannelIds=string.Join(", ",old.ChannelIds.Split(", ",StringSplitOptions.RemoveEmptyEntries).Append("LCN ?"+candidate.Lcn).Distinct()),EvidenceStatus="Tentative LCN correlation; manual verification required"};if(DiscoveryNames.Generated(old.Name))updated=updated with{Name=DiscoveryNames.Label(updated)};store.Upsert(updated);Rebuild(updated.Id);Notify("Candidate LCN labeled; map remains unconfirmed. Undo restores this label.");}
}
